import math

# Invented z-table: service level -> standard normal quantile
Z_TABLE = {
    0.90: 1.2816,
    0.95: 1.6449,
    0.99: 2.3263,
}


def safety_stock(service_level, sigma_daily_demand, lead_time_days):
    """Safety stock = z * sigma * sqrt(lead time)."""
    if service_level not in Z_TABLE:
        raise KeyError(
            f"Unsupported service level {service_level!r}; "
            f"supported levels: {sorted(Z_TABLE)}"
        )
    z = Z_TABLE[service_level]
    return z * sigma_daily_demand * math.sqrt(lead_time_days)


def reorder_point(avg_daily_demand, service_level, sigma_daily_demand, lead_time_days):
    """ROP = avg daily demand * lead time + safety stock."""
    return avg_daily_demand * lead_time_days + safety_stock(
        service_level, sigma_daily_demand, lead_time_days
    )
